function crosshair(p,x,y,size,time,color='#b5c8a4'){p.save();p.translate(x,y);p.strokeStyle=color;p.lineWidth=2;for(const side of [-1,1]){line(p,side*size,-8,side*size,-size*.45,color);line(p,side*size,-size*.45,side*(size-10),-size*.45,color);line(p,side*size,8,side*size,size*.45,color);line(p,side*size,size*.45,side*(size-10),size*.45,color);}diamond(p,0,0,3,color);p.restore();}
function cannon(p,c,k,time){const im=image('gunner-siege-cannon');if(!k.emplacement||!im.complete||!im.naturalWidth)return;const angle=k.aimAngle??(c.facing?Math.PI:0),elapsed=time-(k.shotAt??-99),recoil=elapsed>=0&&elapsed<.28?Math.sin(elapsed/.28*Math.PI)*(k.recoil||3):0;p.save();p.translate(c.x,c.y+12);p.imageSmoothingEnabled=false;p.drawImage(im,19,570,1487,362,-36,-17,120,29);p.drawImage(im,19,128,650,445,-36,-53,53,36);p.translate(0,-32);p.rotate(angle);p.drawImage(im,540,280,965,265,-8-recoil,-12,78,22);p.fillStyle='#ead08c';p.fillRect(-7,-8,9,16);p.restore();}
