function ground(p,g,time){if(g.s.active!==9||!g.c.gunner)return;const k=g.c.gunner;p.save();if(k.coordinates){crosshair(p,k.coordinates.x,k.coordinates.y,k.coordinates.radius,time,'#bdc8a4');for(let i=-1;i<=1;i++)line(p,k.coordinates.x-80,k.coordinates.y+i*25,k.coordinates.x+80,k.coordinates.y+i*25,'#65775e',1);}for(const s of k.shells){p.globalAlpha=.35;crosshair(p,s.to.x,s.to.y,s.kind==='bomblet'?14:24,time,'#c2a578');}p.restore();}
function state(p,g,time){if(g.s.active!==9||!g.c.gunner)return;const k=g.c.gunner,c=g.c;p.save();cannon(p,c,k,time);for(const b of k.bolts)bullet(p,b);for(const s of k.shells)shell(p,s);for(const e of c.enemies)if(e.hp>0&&e.gunMark>0){atlas(p,'gunner-rune',0,1,e.x,e.y-65,25+e.gunMark*5,25+e.gunMark*5,0,2);for(let i=0;i<e.gunMark;i++)casing(p,e.x-8+i*8,e.y-49,pi/2,4);}if(k.charges.length)for(let i=0;i<k.charges.length;i++)diamond(p,c.x-12+i*12,c.y-64,4,colors[k.charges[i]]);p.font='bold 9px sans-serif';p.textAlign='center';p.fillStyle='#efdbab';let text='';if([0,1,3].includes(g.h.cell))text=c.reloadTime>0?'재장전 '+c.reloadTime.toFixed(1)+'초':'탄창 '+c.meters.ammo+'/'+(g.h.cell===3?12:g.h.cell===1?8:6);if(g.h.cell===1)text+=' · 집중 '+k.focus;if(g.h.cell===6)text=(k.emplacement?'공성 · ':'')+'열기 '+Math.ceil(k.heat)+(k.overheat>0?' · 과열':'');if(g.h.cell===4)text='속성탄 '+k.charges.length+'/3';if(text)p.fillText(text,c.x,c.y-74);if(k.overheat>0)root.RPG_SKILL_FX?.smoke(p,c.x+25,c.y-8,time%.8,35,.35);p.restore();}
